import{_ as n,a0 as o,w as p,s as r,I as t,x as e,a1 as l,A as s,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"用 Pi-hole 和 Orange Pi 阻止家中所有設備上的廣告 | LCTT x X-CMD","titleTemplate":false,"description":"用 Pi-hole 和 Orange Pi 阻止家中所有設備上的廣告 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Pi-hole 和 Orange Pi 阻止家中所有設備上的廣告 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Pi-hole 和 Orange Pi 阻止家中所有設備上的廣告 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170107 Block Ads on All Your Devices at Home with Pi-hole and an Orange Pi","title":"用 Pi-hole 和 Orange Pi 阻止家中所有設備上的廣告","tag":"201702","desc":""},"relativePath":"201702/20170107 Block Ads on All Your Devices at Home with Pi-hole and an Orange Pi.md","filePath":"[post].md"}'),h={name:"201702/20170107 Block Ads on All Your Devices at Home with Pi-hole and an Orange Pi.md"};function g(u,i,P,m,k,b){const a=o("Link");return p(),r("div",null,[i[23]||(i[23]=t("h1",{id:"用-pi-hole-和-orange-pi-阻止家中所有設備上的廣告",tabindex:"-1"},[e("用 Pi-hole 和 Orange Pi 阻止家中所有設備上的廣告 "),t("a",{class:"header-anchor",href:"#用-pi-hole-和-orange-pi-阻止家中所有設備上的廣告","aria-label":"Permalink to “用 Pi-hole 和 Orange Pi 阻止家中所有設備上的廣告”"},"​")],-1)),t("p",null,[i[1]||(i[1]=e("你是否很惱火地發現你的瀏覽器、智能手機和平板上不裝廣告攔截器不行？ 至少我是這樣的。我家裏有一些“智能”設備，但是它們似乎沒有任何類型的廣告攔截軟件。 好了，我瞭解到 ",-1)),l(a,{href:"https://pi-hole.net/"},{default:s(()=>[...i[0]||(i[0]=[e("Pi-hole",-1)])]),_:1}),i[2]||(i[2]=e(" 是一個可以運行在樹莓派板子上的廣告攔截軟件，它能在各種廣告到達你的設備之前攔截它們。它允許你將任何域加入到黑名單或白名單，並且它有一個很好的儀表盤面板，可以讓你深入瞭解你的家庭網絡最常訪問的域/網站、最活躍的設備和最常見的廣告商。",-1))]),i[24]||(i[24]=d(`<p>Pi-hole 原本是運行在樹莓派上的，但我想知道它能否在我運行 Armbian Linux 的廉價 Orange Pi 上運行。 好吧，它絕對可以！下面是我讓 Pi-hole 能快速運行的方法。</p><h3 id="安裝-pi-hole" tabindex="-1">安裝 Pi-hole <a class="header-anchor" href="#安裝-pi-hole" aria-label="Permalink to “安裝 Pi-hole”">​</a></h3><p>安裝 Pi-hole 是使用終端完成的，所以打開你的 Orange Pi 桌面上的終端或使用 ssh 連接。</p><p>因為需要下載軟件，所以進入到一個你選定的目錄，確保你有寫入權限。像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd &lt;your preferred directory&gt;/</span></span></code></pre></div><p>我沒有選擇 Pi-hole 主頁上的“單條命令”安裝方式。 我的意思是，他們在那條命令下面寫着“用管道到 bash 可能是危險的”，本地安裝“更安全”。所以，這裏是我的本地安裝步驟：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>git clone --depth 1 https://github.com/pi-hole/pi-hole.git Pi-hole</span></span>
<span class="line"><span>cd Pi-hole/automated\\ install/</span></span>
<span class="line"><span>./basic-install.sh</span></span></code></pre></div><p>如果你沒有以 root 用户身份登錄，那麼這個安裝腳本將提示你輸入密碼，然後再繼續。 如果需要，腳本將下載並安裝一些必備的 Linux 軟件包。接着它會顯示一個紅藍界面，提示你回答有關如何配置 Pi-hole 的幾個問題。以我的經驗，直接接受默認值就可以了，我後來發現 Pi-hole 的 web 應用可以讓你更改設置，比如 DNS 提供商。</p><p>該腳本將告訴你在圖形界面和終端中 Pi-hole 的密碼。 請記住該密碼！</p><p>腳本還會告訴你 Pi-hole 的網址，應該像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://&lt;your pi’s IP address&gt;/admin</span></span></code></pre></div><p>或者類似這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://orangepipc/admin</span></span></code></pre></div><p>輸入 Pi-hole 密碼，接着你會看到像下面這樣的漂亮的儀表盤面板：</p><p><img src="https://i1.wp.com/piboards.com/wp-content/uploads/2017/01/ph-hole.png?resize=640%2C532" alt="Ph-hole"></p><p>請記住更改家庭網絡路由器上的 DNS 設置並使用你的 Orange Pi 的地址。 否則，廣告不會被過濾！</p><p>上面的説明與 Pi-hole 網站提供的替代“安全”方法大致相同，儘管 Armbian 沒有被列為官方支持的操作系統。我相信這些説明應該在樹莓派或其他運行某種形式的基於 Debian 的 Linux 操作系統的 Pi 上工作。但是，我並沒有測試這一點，所以期待聽到你的經驗（請給我留下簡短的評論）。</p><h3 id="思考和觀察" tabindex="-1">思考和觀察 <a class="header-anchor" href="#思考和觀察" aria-label="Permalink to “思考和觀察”">​</a></h3><p>運行 Pi-hole 一段時間，並研究了在 Pi-hole 面板上出現的信息後，我發現有很多我不知道的網絡活動在進行，而它們並不都是我批准的活動。例如，有一些我不知道的關於遊戲程序的“有趣”連接從我的孩子的設備上發出，還有社交網絡程序顯然一直在給我發送騷擾數據。總之，無論是否是無害流量，我很高興減少了流量負載，即使僅減少了一點點……我的意思是，為什麼我應該允許我不想要的或者不關心的應用程序和廣告吃掉我的網絡流量？好吧，現在他們被封鎖了。</p>`,19)),t("p",null,[i[4]||(i[4]=e("像這樣為 Orange Pi 設置廣告屏蔽很便宜、容易，限制一些不必要的流量在我的家庭網絡中進出（特別是與孩子們相關的）使我感到放鬆多了。如果有興趣，你可以看看我的上一篇文章，如何",-1)),l(a,{href:"http://piboards.com/2017/01/04/easy-set-up-orange-pi/"},{default:s(()=>[...i[3]||(i[3]=[e("輕鬆設置一個 Orange Pi",-1)])]),_:1}),i[5]||(i[5]=e("，並使用下面的鏈接來查看 Orange Pi 是多麼便宜。我相信這是一個值得的投資。",-1))]),t("ul",null,[t("li",null,[i[7]||(i[7]=e("Amazon 上的 Orange Pi （受益鏈接）：  ",-1)),l(a,{href:"https://www.amazon.com/gp/product/B018W6OTIM/ref=as_li_tl?ie=UTF8&camp=1789&creative=9325&creativeASIN=B018W6OTIM&linkCode=as2&tag=piboards-20&linkId=ac292a536d58eabf1ee73e2c575e1111"},{default:s(()=>[...i[6]||(i[6]=[e("Orange Pi PC Single Board Computer Quad Core ARM Cortex-A7 1GB DDR3 4K Decode",-1)])]),_:1})]),t("li",null,[l(a,{href:"http://s.click.aliexpress.com/e/bAMVj2R"},{default:s(()=>[...i[8]||(i[8]=[e("AliExpress 上的 Orange Pi 商店",-1)])]),_:1}),i[9]||(i[9]=e(" （受益鏈接）",-1))])]),i[25]||(i[25]=t("p",null,"更新：具有諷刺意味的是，如果你成功地按照這篇文章設置了 Pi-hole，這個站點上（s.click.aliexpress.com）的受益鏈接會被屏蔽，是否將它加入到白名單取決於你。",-1)),i[26]||(i[26]=t("hr",null,null,-1)),t("p",null,[i[11]||(i[11]=e("via: ",-1)),l(a,{href:"http://piboards.com/2017/01/07/block-ads-on-all-your-devices-at-home-with-pi-hole-and-an-orange-pi/"},{default:s(()=>[...i[10]||(i[10]=[e("http://piboards.com/2017/01/07/block-ads-on-all-your-devices-at-home-with-pi-hole-and-an-orange-pi/",-1)])]),_:1})]),t("p",null,[i[15]||(i[15]=e("作者：",-1)),l(a,{href:"http://piboards.com/author/piguy/"},{default:s(()=>[...i[12]||(i[12]=[e("MIKE WILMOTH",-1)])]),_:1}),i[16]||(i[16]=e(" 譯者：",-1)),l(a,{href:"https://github.com/geekpi"},{default:s(()=>[...i[13]||(i[13]=[e("geekpi",-1)])]),_:1}),i[17]||(i[17]=e(" 校對：",-1)),l(a,{href:"https://github.com/jasminepeng"},{default:s(()=>[...i[14]||(i[14]=[e("jasminepeng",-1)])]),_:1})]),t("p",null,[i[20]||(i[20]=e("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...i[18]||(i[18]=[e("LCTT",-1)])]),_:1}),i[21]||(i[21]=e(" 原創編譯，",-1)),l(a,{href:"https://linux.cn/"},{default:s(()=>[...i[19]||(i[19]=[e("Linux中國",-1)])]),_:1}),i[22]||(i[22]=e(" 榮譽推出",-1))])])}const x=n(h,[["render",g]]);export{T as __pageData,x as default};
